args.sparql:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?label ?dboBirth ?dbpBirth WHERE {
  VALUES ?person { dbr:Shahanuddin_Choudhury dbr:Domenico_Distilo }
  OPTIONAL { ?person rdfs:label ?label . FILTER(lang(?label) = "en") }
  OPTIONAL { ?person dbo:birthDate ?dboBirth }
  OPTIONAL { ?person dbp:birthDate ?dbpBirth }
} ORDER BY ?person

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?label ?birthDate WHERE {
  VALUES ?person { dbr:Shahanuddin_Choudhury dbr:Domenico_Distilo }
  OPTIONAL { ?person rdfs:label ?label . FILTER(lang(?label) = "en") }
  OPTIONAL { ?person dbo:birthDate ?dboBirth }
  OPTIONAL { ?person dbp:birthDate ?dbpBirth }
  BIND(COALESCE(?dboBirth, ?dbpBirth) AS ?birthDate)
  FILTER(BOUND(?birthDate))
}
ORDER BY ASC(?birthDate)
LIMIT 1

